    @classmethod
    def get_by_code(cls, code: str) -> Optional[DetailedICD10Record]:
        cls.initialize()
        return cls._DATA.get(code.strip().upper())

    @classmethod
    def count(cls) -> int:
        cls.initialize()
        return len(cls._DATA)
